fn generate_oracle_code (output : & str) -> Result < () > { println ! ("🔮 Generating syscall oracle types and macros...") ; let oracle_code = generate_oracle_types () ; let formatted_code = format ! ("// Auto-generated syscall oracle types and macros\n// Generated by syscall-oracle tool\n\n{}" , oracle_code . to_string ()) ; std :: fs :: write (output , formatted_code) ? ; println ! ("✅ Generated oracle types: {}" , output) ; println ! ("📋 Includes:") ; println ! ("   • SystemOracle trait") ; println ! ("   • FileSystemOracle, ProcessOracle, NetworkOracle") ; println ! ("   • Type-safe wrapper macros") ; println ! ("   • DAO governance types") ; Ok (()) }